properties.query:
let lookback = 1h;
let binSize = 10m;
let MinDistinctRules = 8;
let MinDistinctUris = 15;
let MinHits = 40;
let AIAgentUA = dynamic(["GPTBot", "ChatGPT-User", "OAI-SearchBot", "ClaudeBot", "Claude-User", "Claude-SearchBot",
    "PerplexityBot", "Perplexity-User", "Meta-ExternalAgent", "Bytespider", "CCBot", "Google-Extended"]);
let AutomationUA = dynamic(["python-requests", "aiohttp", "httpx", "Go-http-client", "curl/", "Wget", "node-fetch",
    "axios", "HeadlessChrome", "Playwright", "puppeteer", "nuclei", "sqlmap"]);
let Bursts = AGWFirewallLogs
    | where TimeGenerated > ago(lookback)
    | where Action in ("Matched", "Blocked", "Detected")
    | summarize Hits = count(), DistinctRules = dcount(RuleId), DistinctUris = dcount(RequestUri),
                Rules = make_set(RuleId, 50), Messages = make_set(Message, 20), SampleUris = make_set(RequestUri, 20),
                Hosts = make_set(Hostname, 5), Actions = make_set(Action, 3)
             by ClientIp, Window = bin(TimeGenerated, binSize)
    | where DistinctRules >= MinDistinctRules and DistinctUris >= MinDistinctUris and Hits >= MinHits;
let UAContext = AGWAccessLogs
    | where TimeGenerated > ago(lookback)
    | where ClientIp in ((Bursts | project ClientIp))
    | summarize UserAgents = make_set(UserAgent, 10), Requests = count(),
                Status4xx = countif(HttpStatus between (400 .. 499)), Status5xx = countif(HttpStatus >= 500),
                Status2xx = countif(HttpStatus between (200 .. 299))
             by ClientIp;
let TI = ThreatIntelIndicators
    | where TimeGenerated > ago(14d) and IsActive == true
    | where ObservableKey has "ipv4-addr" or ObservableKey has "ipv6-addr"
    | summarize TIConfidence = max(Confidence) by ClientIp = ObservableValue;
Bursts
| join kind=leftouter UAContext on ClientIp
| join kind=leftouter TI on ClientIp
| extend UAText = tostring(UserAgents)
| extend ClaimsAIAgent = UAText has_any (AIAgentUA),
         AutomationClient = UAText has_any (AutomationUA),
         Got2xxDuringBurst = coalesce(Status2xx, 0) > 0 and Actions has "Matched"
| extend Severity = case(Got2xxDuringBurst or coalesce(TIConfidence, 0) >= 70, "High",
                         "Medium")
| project Window, ClientIp, Hits, DistinctRules, DistinctUris, Rules, Messages, SampleUris, Hosts, Actions, UserAgents,
          ClaimsAIAgent, AutomationClient, Requests, Status2xx, Status4xx, Status5xx, TIConfidence, Severity
